-- Deep polish for D1a mandatory straight-ahead wording.
START TRANSACTION;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Wat betekent dit verkeersbord?', q.question_en = 'What does this traffic sign mean?', q.question_fr = 'Que signifie ce panneau de signalisation ?', q.question_ar = 'ما معنى هذه العلامة المرورية؟', q.explanation_nl = 'Dit verkeersbord verplicht de bestuurder rechtdoor te rijden. Naar links of rechts afslaan is niet toegestaan.', q.explanation_en = 'This traffic sign requires the driver to continue straight ahead. Turning left or right is not allowed.', q.explanation_fr = 'Ce panneau oblige le conducteur a aller tout droit. Tourner a gauche ou a droite n est pas autorise.', q.explanation_ar = 'تُلزم هذه العلامة المرورية السائق بالسير إلى الأمام مباشرة. الانعطاف يمينًا أو يسارًا غير مسموح.' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q01';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Verplichting rechtdoor', c.text_en = 'Mandatory straight ahead', c.text_fr = 'Obligation d''aller tout droit', c.text_ar = 'طريق إجباري إلى الأمام' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q01' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Verplichting links afslaan', c.text_en = 'Mandatory left turn', c.text_fr = 'Obligation de tourner a gauche', c.text_ar = 'إلزامية القيادة باتجاه اليسار' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q01' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Verplichting rechts afslaan', c.text_en = 'Mandatory right turn', c.text_fr = 'Obligation de tourner a droite', c.text_ar = 'إلزامية القيادة باتجاه اليمين' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q01' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Tot welke categorie verkeersborden behoort dit bord?', q.question_en = 'To which category of traffic signs does this sign belong?', q.question_fr = 'A quelle categorie de panneaux de signalisation appartient ce panneau ?', q.question_ar = 'إلى أي فئة تُصنَّف هذه العلامة المرورية؟', q.explanation_nl = 'Dit is een gebodsbord. Het verplicht bestuurders de aangeduide richting te volgen.', q.explanation_en = 'This is a mandatory sign. It requires drivers to follow the indicated direction.', q.explanation_fr = 'Il s agit d un panneau d obligation. Il oblige les conducteurs a suivre la direction indiquee.', q.explanation_ar = 'هذه العلامة المرورية من علامات الإلزام. وهي تُلزم السائقين باتباع الاتجاه المشار إليه.' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q02';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Gebodsborden', c.text_en = 'Mandatory signs', c.text_fr = 'Panneaux d''obligation', c.text_ar = 'العلامات الإلزامية' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q02' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Verbodsborden', c.text_en = 'Prohibition signs', c.text_fr = 'Panneaux d''interdiction', c.text_ar = 'علامات الحظر' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q02' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Parkeerborden', c.text_en = 'Parking signs', c.text_fr = 'Panneaux de stationnement', c.text_ar = 'علامات الوقوف' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q02' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Wat verwacht dit bord van u als bestuurder op dit kruispunt?', q.question_en = 'What does this sign expect of you as a driver at this junction?', q.question_fr = 'Qu''attend ce panneau de vous en tant que conducteur a ce carrefour ?', q.question_ar = 'ماذا تتوقع هذه العلامة المرورية منك كسائق في هذا التقاطع؟', q.explanation_nl = 'Dit verkeersbord verplicht u de richting van de pijl te volgen. Afslaan is hier niet toegestaan.', q.explanation_en = 'This traffic sign requires you to follow the direction shown by the arrow. Turning is not allowed here.', q.explanation_fr = 'Ce panneau vous oblige a suivre la direction indiquee par la fleche. Tourner n est pas autorise ici.', q.explanation_ar = 'تفرض هذه العلامة المرورية اتباع الاتجاه الذي يشير إليه السهم. الانعطاف غير مسموح هنا.' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q03';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Rechtdoor rijden zoals de pijl aangeeft', c.text_en = 'Drive straight ahead as indicated by the arrow', c.text_fr = 'Aller tout droit comme indique par la fleche', c.text_ar = 'السير للأمام كما تشير السهم' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q03' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Vaart minderen en voorrang verlenen aan kruisend verkeer', c.text_en = 'Slow down and give way to crossing traffic', c.text_fr = 'Ralentir et ceder le passage au trafic croisant', c.text_ar = 'تباطؤ وإعطاء الأولوية للمرور المتقاطع' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q03' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Stoppen en links of rechts afslaan indien de weg vrij is', c.text_en = 'Stop and turn left or right if the road is clear', c.text_fr = 'S''arreter et tourner a gauche ou a droite si la route est libre', c.text_ar = 'التوقف والانعطاف يساراً أو يميناً إذا كان الطريق خالياً' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q03' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'U nadert een kruispunt en dit bord staat voor u, maar uw bestemming ligt links. Wat moet u doen?', q.question_en = 'You are approaching a junction and this sign is ahead of you, but your destination is to the left. What must you do?', q.question_fr = 'Vous approchez d un carrefour et ce panneau se trouve devant vous, mais votre destination est a gauche. Que devez-vous faire ?', q.question_ar = 'أنت تقترب من تقاطع وهذه العلامة المرورية أمامك، لكن وجهتك تقع على اليسار. ماذا يجب عليك فعله؟', q.explanation_nl = 'Dit verkeersbord is wettelijk bindend. Ook als uw bestemming links ligt, moet u rechtdoor rijden.', q.explanation_en = 'This traffic sign is legally binding. Even if your destination is on the left, you must continue straight ahead.', q.explanation_fr = 'Ce panneau est juridiquement contraignant. Meme si votre destination se trouve a gauche, vous devez continuer tout droit.', q.explanation_ar = 'هذه العلامة المرورية ملزمة قانونيًا. حتى لو كانت وجهتك على اليسار، يجب عليك المتابعة إلى الأمام مباشرة.' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q04';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Rechtdoor rijden en verderop een andere route kiezen', c.text_en = 'Go straight ahead and find an alternative route further on', c.text_fr = 'Aller tout droit et trouver un itineraire alternatif plus loin', c.text_ar = 'السير للأمام واختيار طريق بديل في وقت لاحق' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q04' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Linksaf slaan want uw bestemming heeft prioriteit', c.text_en = 'Turn left because your destination takes priority', c.text_fr = 'Tourner a gauche car votre destination est prioritaire', c.text_ar = 'الانعطاف يساراً لأن وجهتك لها الأولوية' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q04' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Stoppen en wachten tot het kruispunt vrij is om dan links af te slaan', c.text_en = 'Stop and wait until the junction is clear to then turn left', c.text_fr = 'Vous arreter et attendre que le carrefour soit libre pour tourner a gauche', c.text_ar = 'التوقف والانتظار حتى يخلو التقاطع للانعطاف يساراً' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q04' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Uw navigatiesysteem zegt dat u linksaf moet slaan, maar dit bord staat aan het kruispunt. Wat doet u?', q.question_en = 'Your navigation system tells you to turn left, but this sign is posted at the junction. What do you do?', q.question_fr = 'Votre systeme de navigation vous indique de tourner a gauche, mais ce panneau est place au carrefour. Que faites-vous ?', q.question_ar = 'يطلب منك جهاز الملاحة الانعطاف يسارًا، لكن هذه العلامة المرورية موجودة عند التقاطع. ماذا تفعل؟', q.explanation_nl = 'Verkeersborden hebben voorrang op navigatieapparatuur. U moet rechtdoor rijden zoals het bord voorschrijft.', q.explanation_en = 'Traffic signs take precedence over navigation devices. You must continue straight ahead as required by the sign.', q.explanation_fr = 'Les panneaux de signalisation ont priorite sur les appareils de navigation. Vous devez poursuivre tout droit comme le panneau l impose.', q.explanation_ar = 'العلامات المرورية لها الأولوية على أجهزة الملاحة. يجب عليك المتابعة إلى الأمام وفقًا لما تفرضه العلامة.' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q05';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Het bord volgen en rechtdoor rijden; de GPS aanpassen na het kruispunt', c.text_en = 'Follow the sign and go straight ahead; recalculate the GPS after the junction', c.text_fr = 'Suivre le panneau et aller tout droit; recalculer le GPS apres le carrefour', c.text_ar = 'اتباع العلامة المرورية والسير للأمام؛ وإعادة حساب مسار GPS بعد التقاطع' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q05' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'De GPS volgen want die kent de meest recente verkeerssituatie', c.text_en = 'Follow the GPS because it has the most up-to-date traffic information', c.text_fr = 'Suivre le GPS car il dispose des informations de circulation les plus recentes', c.text_ar = 'اتباع GPS لأنّ لديه أحدث معلومات حركة المرور' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q05' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Stoppen om de GPS opnieuw in te stellen voor u verder rijdt', c.text_en = 'Stop to reset the GPS before continuing', c.text_fr = 'Vous arreter pour reinitialiser le GPS avant de continuer', c.text_ar = 'التوقف لإعادة ضبط GPS قبل المتابعة' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q05' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Geldt dit verkeersbord alleen voor personenwagens of voor alle bestuurders?', q.question_en = 'Does this traffic sign apply only to cars or to all drivers?', q.question_fr = 'Ce panneau s applique-t-il uniquement aux voitures ou a tous les conducteurs ?', q.question_ar = 'هل تنطبق هذه العلامة المرورية فقط على السيارات أم على جميع السائقين؟', q.explanation_nl = 'Gebodsborden gelden voor alle weggebruikers, tenzij een onderbord een uitzondering voor een bepaalde categorie aangeeft.', q.explanation_en = 'Mandatory signs apply to all road users unless a supplementary sign states an exception for a specific category.', q.explanation_fr = 'Les panneaux d obligation s appliquent a tous les usagers de la route, sauf si un panneau complementaire prevoit une exception pour une categorie donnee.', q.explanation_ar = 'تنطبق علامات الإلزام على جميع مستخدمي الطريق، ما لم تحدد علامة تكميلية استثناءً لفئة معينة.' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q06';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Voor alle bestuurders, tenzij een onderbord een specifieke uitzondering maakt', c.text_en = 'To all drivers, unless a supplementary sign makes a specific exception', c.text_fr = 'A tous les conducteurs, sauf si un panneau complementaire prevoit une exception specifique', c.text_ar = 'على جميع السائقين، ما لم تُحدد علامة مرورية تكميلية استثناءً معيناً' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q06' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Alleen voor personenwagens; vrachtwagens mogen afslaan', c.text_en = 'Only to cars; trucks may turn', c.text_fr = 'Uniquement aux voitures; les camions peuvent tourner', c.text_ar = 'على السيارات فقط؛ يجوز للشاحنات الانعطاف' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q06' AND c.display_order = 2;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Alleen voor motorvoertuigen; fietsers mogen vrij rijden', c.text_en = 'Only to motor vehicles; cyclists may ride freely', c.text_fr = 'Uniquement aux vehicules a moteur; les cyclistes peuvent circuler librement', c.text_ar = 'على المركبات الآلية فقط؛ يجوز لراكبي الدراجات السير بحرية' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q06' AND c.display_order = 3;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'Dit bord staat aan een kruispunt en de weg rechts is leeg. Mag u rechtsaf slaan?', q.question_en = 'This sign is posted at a junction and the road to the right is empty. May you turn right?', q.question_fr = 'Ce panneau est place a un carrefour et la route a droite est vide. Pouvez-vous tourner a droite ?', q.question_ar = 'هذه العلامة المرورية موجودة عند تقاطع والطريق على اليمين خالٍ. هل يمكنك الانعطاف يمينًا؟', q.explanation_nl = 'Dit verkeersbord verbiedt elke richtingsverandering. Het feit dat de weg rechts leeg is, verandert daar niets aan.', q.explanation_en = 'This traffic sign prohibits any change of direction. An empty road on the right does not change that obligation.', q.explanation_fr = 'Ce panneau interdit tout changement de direction. Le fait que la route a droite soit vide ne change rien a cette obligation.', q.explanation_ar = 'تحظر هذه العلامة المرورية أي تغيير في الاتجاه. خلو الطريق على اليمين لا يغيّر هذا الالتزام.' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q07';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Neen, u moet rechtdoor rijden; rechtsaf slaan is niet toegestaan.', c.text_en = 'No, you must continue straight ahead; turning right is not allowed.', c.text_fr = 'Non, vous devez continuer tout droit; tourner a droite n est pas autorise.', c.text_ar = 'لا، يجب عليك المتابعة إلى الأمام؛ الانعطاف يمينًا غير مسموح.' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q07' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Ja, als de weg vrij is mag u rechtsaf slaan.', c.text_en = 'Yes, if the road is empty you may turn right.', c.text_fr = 'Oui, si la route est libre vous pouvez tourner a droite.', c.text_ar = 'نعم، إذا كان الطريق خاليًا يمكنك الانعطاف يمينًا.' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q07' AND c.display_order = 2;
UPDATE sign_questions q JOIN road_signs rs ON rs.id = q.sign_id SET q.question_nl = 'U hebt uw afslag gemist en staat nu voor dit bord. Mag u keren om naar uw afslag terug te gaan?', q.question_en = 'You missed your exit and are now facing this sign. May you make a U-turn to return to your exit?', q.question_fr = 'Vous avez manque votre sortie et vous vous trouvez maintenant devant ce panneau. Pouvez-vous faire demi-tour pour revenir vers votre sortie ?', q.question_ar = 'لقد فاتك المخرج وأنت الآن أمام هذه العلامة المرورية. هل يمكنك الاستدارة للعودة إلى مخرجك؟', q.explanation_nl = 'Dit verkeersbord verplicht u alleen rechtdoor te rijden. Keren is een richtingsverandering en is hier dus niet toegestaan.', q.explanation_en = 'This traffic sign requires you to continue straight ahead only. A U-turn is a change of direction and is therefore not allowed here.', q.explanation_fr = 'Ce panneau vous oblige a continuer tout droit uniquement. Faire demi-tour est un changement de direction et n est donc pas autorise ici.', q.explanation_ar = 'تُلزمك هذه العلامة المرورية بالمتابعة إلى الأمام فقط. الاستدارة تُعد تغييرًا في الاتجاه، ولذلك فهي غير مسموحة هنا.' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q08';
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Neen, u moet rechtdoor rijden; keren is hier niet toegestaan.', c.text_en = 'No, you must continue straight ahead; a U-turn is not allowed here.', c.text_fr = 'Non, vous devez continuer tout droit; faire demi-tour n est pas autorise ici.', c.text_ar = 'لا، يجب عليك المتابعة إلى الأمام؛ الاستدارة تغيير اتجاه غير مسموح هنا.' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q08' AND c.display_order = 1;
UPDATE sign_choices c JOIN sign_questions q ON q.id = c.question_id JOIN road_signs rs ON rs.id = q.sign_id SET c.text_nl = 'Ja, als u de afslag hebt gemist mag u meteen keren.', c.text_en = 'Yes, if you missed the exit you may make a U-turn immediately.', c.text_fr = 'Oui, si vous avez manque la sortie vous pouvez faire demi-tour immediatement.', c.text_ar = 'نعم، إذا فاتك المخرج يمكنك الاستدارة مباشرة.' WHERE rs.sign_code = 'D1a' AND q.question_ref = 'D1a_Q08' AND c.display_order = 2;
COMMIT;
